"""Apply UI99 after the pinned UI97 runtime (UI98 changes hosted routing only)."""
from __future__ import annotations
import base64,hashlib,json,sys,zlib
from pathlib import Path,PurePosixPath
PARENT_MANIFEST_SHA256='95f800876f7278c8c0ad43e97e76a75deb5cc23a987aaebb582ba7285bc9e52b'
TARGET_VARIANT='workspace-ui99-independent-browser-tabs-2026-10-04'
FILES={'app/static/app.js': {'before': '7d34fe50cd1ff58670220177628bcfbbc2863a68bd3bbf8c9b75812a7fe9628c', 'after': 'a8a669c944e2a76a23264cbb8e7025147b4b7a6f6acffa76b80f05a136d10ab0', 'bytes': 172755, 'payload': ''}, 'app/static/browser_workspace.js': {'before': None, 'after': '87b59a35bc2df44a92353537374c635d75715031e6e82c0708e742cb16858340', 'bytes': 6946, 'payload': ''}, 'app/static/index.html': {'before': 'bdda0632747e5349aaff1b4999119c414db9bfe6ccbf9b4684a44f7df94c52ff', 'after': '2b5cf4a7d535324d2b559d348993bcbc79c85a7a33a1db075ee3b68d565822f2', 'bytes': 24816, 'payload': ''}, 'app/static/save_status.js': {'before': '8a0e584bb71cb8cf4194eb743152d36debadedf1f3744621c1f9706f3af05297', 'after': 'da539add2d6441c93cb7ed465956f2ad8d27bec81fe22b1646c739249c431d5f', 'bytes': 15022, 'payload': ''}, 'app/static/save_status_ui.js': {'before': '32997665df9a81ee1c2bd733964e01adeede5ef91731924e19236ba8760a9168', 'after': '901e4e8278e14884cd83e730a4dd1f1b907ab46eb7e6ef1d91c2df1827b87892', 'bytes': 12916, 'payload': ''}, 'app/static/sw.js': {'before': '5e1ce04f09605d87c7d9d03cf86ab86fa8dfeaf2bb6f9f5afc3647647c57dbe2', 'after': 'ab64c17d1f07f3655db2bf6d3ec43032c26889ad2cfb98ebbdb1bf4dca608b7e', 'bytes': 13450, 'payload': ''}, 'UI_PATCH.json': {'before': 'd7c09b31adc861c54e4d4053c8433ec9db95495f91eb78fe25df9bd5b898cada', 'after': '5cf23ab6a83b5dec81be106e916a863ee196f89b1ef170e533dfdd406b49f9f3', 'bytes': 2183, 'payload': ''}}

def apply(destination: Path) -> None:
    manifest_path=destination/'RELEASE_FILES.json'
    raw=manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=PARENT_MANIFEST_SHA256:
        raise ValueError('UI99 requires the exact UI97 source manifest. Do not deploy.')
    manifest=json.loads(raw)
    for name,expected in manifest['files'].items():
        relative=PurePosixPath(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise ValueError('Unsafe source manifest path.')
        path=destination.joinpath(*relative.parts)
        if path.is_symlink() or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise ValueError('UI99 parent resource mismatch: '+name)
    prepared={}
    for name,record in FILES.items():
        path=destination/name
        if record['before'] is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('UI99 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI99 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        data+=dec.flush()
        if not dec.eof or dec.unused_data or dec.unconsumed_tail or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI99 payload integrity failure: '+name)
        prepared[name]=data
    for name,data in prepared.items():
        path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
        manifest['files'][name]=FILES[name]['after']
    manifest['variant']=TARGET_VARIANT
    manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
    for name,expected in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=expected:
            raise ValueError('Derived UI99 integrity failure: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI99: independent browser tabs and saved draft recovery; UI98 gateway and email recovery retained.')
